package top.monitorglobal.tv;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w1280dp-h720dp-land-hdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class RainOverlayTest {
 private Object value(Object target,String name)throws Exception{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 private RainForecast.Summary sample(){return new RainForecast.Summary("now","forte","Chuva forte estimada agora",8,4,"Pode terminar em ~30 min a partir de agora",1800000000000L,1800000600000L,true);}
 @Test public void overlayDrawsAndRepeatedPreemptionReleasesDropsAndWindow()throws Exception{
  Context c=RuntimeEnvironment.getApplication();org.robolectric.shadows.ShadowSettings.setCanDrawOverlays(true);RainOverlay rain=new RainOverlay(c);
  for(int i=0;i<20;i++){assertTrue(rain.show(sample(),true,true));View host=(View)value(rain,"current");WindowManager.LayoutParams p=(WindowManager.LayoutParams)host.getLayoutParams();assertTrue((p.flags&WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE)!=0);assertTrue((p.flags&WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE)!=0);RainOverlay.Drops drops=(RainOverlay.Drops)value(rain,"drops");assertNotNull(drops);host.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));host.layout(0,0,1920,1080);host.setAlpha(1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(600));host.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));host.layout(0,0,1920,1080);assertTrue((Boolean)value(drops,"running"));View card=((ViewGroup)host).getChildAt(1);assertTrue(card.getLeft()>500);assertTrue(card.getRight()<=1920);Bitmap b=Bitmap.createBitmap(1920,1080,Bitmap.Config.ARGB_8888);host.draw(new Canvas(b));int visible=0;for(int y=0;y<1080;y+=2)for(int x=0;x<900;x+=2)if(Color.alpha(b.getPixel(x,y))>0)visible++;assertTrue("rain must be drawn outside the card",visible>50);int textPixels=0;for(int y=card.getTop();y<card.getBottom();y++)for(int x=card.getLeft();x<card.getRight();x++){int color=b.getPixel(x,y);if(Color.red(color)>200&&Color.green(color)>200&&Color.blue(color)>200)textPixels++;}assertTrue("the card text must be inside the screen",textPixels>200);if(i==0)try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(System.getProperty("java.io.tmpdir"),"monitor-tv-rain-preview.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();rain.hide();assertNull(value(rain,"current"));assertNull(value(rain,"drops"));assertFalse((Boolean)value(drops,"running"));}
  Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(20));assertNull(value(rain,"current"));
 }
 @Test public void cardOnlyUsesASmallWindowAndAutomaticallyCloses()throws Exception{Context c=RuntimeEnvironment.getApplication();org.robolectric.shadows.ShadowSettings.setCanDrawOverlays(true);RainOverlay rain=new RainOverlay(c);assertTrue(rain.show(sample(),false,false));assertNull(value(rain,"drops"));View host=(View)value(rain,"current");assertTrue(((WindowManager.LayoutParams)host.getLayoutParams()).width>0);Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(14));assertNull(value(rain,"current"));rain.hide();}
 @Test public void noPermissionLeavesNoWindowOrAnimation()throws Exception{Context c=RuntimeEnvironment.getApplication();org.robolectric.shadows.ShadowSettings.setCanDrawOverlays(false);RainOverlay rain=new RainOverlay(c);assertFalse(rain.show(sample(),true,false));assertNull(value(rain,"current"));assertNull(value(rain,"drops"));}
}
